<script setup lang="ts">
import{brand}from'../brand';import{joinTypes,clubDivisions}from'../membership';import{computed,reactive,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{state,login}from'../store';import{api,run}from'../api';import Icon from'../components/Icon.vue';import type{FormInstance,FormRules}from'element-plus'
const route=useRoute(),router=useRouter(),mode=ref<'login'|'register'>(route.query.join?'register':'login'),busy=ref(false),formRef=ref<FormInstance>(),form=reactive({username:'',password:'',name:'',email:'',studentNo:'',department:'',contact:'',grade:'',joinType:route.query.join==='SOCIETY'?'SOCIETY':'CLUB',clubDivision:''})
const rules=computed<FormRules>(()=>({username:[{required:true,message:'请输入用户名',trigger:'blur'},...(mode.value==='register'?[{pattern:/^[a-zA-Z0-9_]{3,32}$/,message:'请输入 3–32 位字母、数字或下划线',trigger:'blur'}]:[])],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:8,max:64,message:'密码长度为 8–64 位',trigger:'blur'}],name:[{required:true,message:'请输入姓名',trigger:'blur'}],email:[{required:true,message:'请输入邮箱',trigger:'blur'},{type:'email',message:'请输入有效邮箱',trigger:'blur'}],studentNo:[{required:true,message:'请输入学号',trigger:'blur'}],department:[{required:true,message:'请输入院系',trigger:'blur'}],contact:[{required:true,message:'请填写联系方式',trigger:'blur'}],grade:[{required:true,message:'请填写年级',trigger:'blur'}]}))
async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;busy.value=true;await run(async()=>{if(mode.value==='register')await api('/auth/register','POST',form);await login(form.username,form.password);const redirect=String(route.query.redirect||'/');router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')?redirect:'/')},mode.value==='login'?'欢迎回到征途俱乐部&社团':'注册成功，加入意向已保存，请在俱乐部展示查看审核状态');busy.value=false}
watch(()=>form.joinType,v=>{if(v!=='CLUB')form.clubDivision=''})
function demo(role:string){mode.value='login';form.username=role;form.password='CampusHub@2026';formRef.value?.clearValidate()}
</script>
<template><div class="page-content auth-page"><div class="auth-visual"><img src="/images/cycling.svg" alt="征途骑行插画"><div class="auth-visual-copy"><Icon name="bike" :size="44"/><span>{{brand.fullName}}</span><h1>下一段征途，<br>我们一起出发。</h1><p>每一次值得纪念的出发，<br>都从勇敢迈出的第一步开始。</p><div class="auth-visual-footer">把热爱，骑成征途。<Icon name="sparkles" :size="22"/></div></div></div><div class="auth-form-panel"><span class="eyebrow">加入征途俱乐部&社团</span><h2>{{mode==='login'?'欢迎回到征途':'注册征途骑友账号'}}</h2><p>{{mode==='login'?'登录后管理入社申请、骑行活动和器材借还。':'选择加入俱乐部或社团，填写资料后提交审核；审核通过后按对应身份使用服务。'}}</p><div class="auth-tabs"><button :class="{active:mode==='login'}" @click="mode='login';formRef?.clearValidate()">账号登录</button><button :class="{active:mode==='register'}" @click="mode='register';formRef?.clearValidate()">注册账号</button></div><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" autocomplete="username" maxlength="32" placeholder="请输入用户名" size="large"/></el-form-item><template v-if="mode==='register'"><el-form-item label="选择加入" required><el-radio-group v-model="form.joinType" aria-label="选择加入俱乐部或社团"><el-radio-button v-for="t in joinTypes" :key="t.value" :value="t.value">{{t.label}}</el-radio-button></el-radio-group></el-form-item><div class="info-box">{{form.joinType==='CLUB'?'俱乐部：系统训练、团队贡献，审核后按身份申请两个场地；器材仍按原借用流程办理。':'社团：参加不定期骑行，仅可在北三骑行室存取个人车辆，不得擅用室内设施。'}}<router-link to="/#membership-options">查看首页完整区别</router-link></div><el-form-item v-if="form.joinType==='CLUB'" label="意向部门（可暂不选择）"><select v-model="form.clubDivision" class="native-select" aria-label="注册意向部门"><option value="">暂未选择</option><option v-for="d in clubDivisions" :key="d" :value="d">{{d}}</option></select></el-form-item><div class="form-grid"><el-form-item label="联系方式" prop="contact"><el-input v-model="form.contact" maxlength="120" placeholder="手机 / 微信 / QQ"/></el-form-item><el-form-item label="所在年级" prop="grade"><el-input v-model="form.grade" maxlength="40" placeholder="例如：2025级"/></el-form-item></div><div class="form-grid"><el-form-item label="姓名" prop="name"><el-input v-model="form.name" maxlength="50" placeholder="你的姓名"/></el-form-item><el-form-item label="学号" prop="studentNo"><el-input v-model="form.studentNo" maxlength="30" placeholder="你的学号"/></el-form-item></div><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" type="email" autocomplete="email" maxlength="120" placeholder="用于联系的邮箱"/></el-form-item><el-form-item label="院系" prop="department"><el-input v-model="form.department" maxlength="100" placeholder="请填写所在学院或院系"/></el-form-item></template><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password :autocomplete="mode==='login'?'current-password':'new-password'" maxlength="64" placeholder="请输入至少 8 位密码" size="large"/></el-form-item><el-button native-type="submit" type="primary" size="large" class="full-width auth-submit" :loading="busy">{{mode==='login'?'登录，开启校园生活':'注册并提交加入意向'}}<Icon name="arrow" :size="18"/></el-button></el-form><div v-if="state.overview.demoEnabled" class="demo-accounts"><span>本地演示 · 点击填入账号</span><div><el-button @click="demo('student')">学生账号</el-button><el-button @click="demo('admin')">管理员账号</el-button></div><small>演示密码：CampusHub@2026</small></div><p class="auth-footnote"><Icon name="shield" :size="14"/>密码加密存储，安全连接你的俱乐部生活。</p></div></div></template>
